// Package storage keeps opaque blobs (uploads, generated files) behind a small
// interface, so a project can start on local disk and move to object storage
// without changing business code.
//
// Keys are generated by the server, never taken from user filenames: one or
// more slash-separated folders and a final name, each made of letters, digits,
// '_' and '-', followed by a lowercase extension, e.g. "T1/S1/IMG.png".
package storage

import (
	"context"
	"errors"
	"fmt"
	"io"
	"mime"
	"os"
	"regexp"
	"strings"
)

// Storage stores whole objects by key. Objects are never overwritten: Put on
// an existing key fails with ErrExists.
type Storage interface {
	Put(ctx context.Context, key string, data []byte) error
	// Open returns ErrNotFound when the key has no object.
	Open(ctx context.Context, key string) (io.ReadSeekCloser, error)
	// Delete removes the object; a missing key is not an error.
	Delete(ctx context.Context, key string) error
}

var (
	// ErrNotFound is returned by Open for a missing key. errors.Is also
	// matches os.ErrNotExist.
	ErrNotFound = fmt.Errorf("storage: object not found: %w", os.ErrNotExist)
	// ErrExists is returned by Put when the key already has an object.
	// errors.Is also matches os.ErrExist.
	ErrExists = fmt.Errorf("storage: object already exists: %w", os.ErrExist)
	// ErrInvalidKey is returned for keys that ValidKey rejects.
	ErrInvalidKey = errors.New("storage: invalid key")
)

// MaxDepth is the most folders a key may have before its final name.
const MaxDepth = 7

var (
	validKey = regexp.MustCompile(`^(?:[A-Za-z0-9_-]{1,128}/){0,7}[A-Za-z0-9_-]{1,128}\.[a-z0-9]{1,10}$`)
	segment  = regexp.MustCompile(`^[A-Za-z0-9_-]{1,128}$`)
	ext      = regexp.MustCompile(`^[a-z0-9]{1,10}$`)
)

// ValidKey reports whether key is a safe storage key. Valid keys cannot
// contain "..", empty segments, a leading slash or any other path syntax.
func ValidKey(key string) bool { return validKey.MatchString(key) }

// Key joins parts with "/" and appends "."+extension, e.g.
// Key("png", tenant, store, id) == "tenant/store/id.png". The last part is
// the file name; the others are folders.
func Key(extension string, parts ...string) (string, error) {
	if len(parts) == 0 || len(parts) > MaxDepth+1 || !ext.MatchString(extension) {
		return "", ErrInvalidKey
	}
	for _, part := range parts {
		if !segment.MatchString(part) {
			return "", ErrInvalidKey
		}
	}
	return strings.Join(parts, "/") + "." + extension, nil
}

// ContentType guesses the media type from the key's extension, falling back
// to application/octet-stream.
func ContentType(key string) string {
	if i := strings.LastIndexByte(key, '.'); i >= 0 {
		if t := mime.TypeByExtension(key[i:]); t != "" {
			return t
		}
	}
	return "application/octet-stream"
}
